const ex = (db, sql) => `<pre class="ex" data-db="${db}">${sql.trim().replace(/&/g, '&amp;').replace(/</g, '&lt;')}</pre>`;
const note = (html) => `<div class="note">${html}</div>`;
const warn = (html) => `<div class="note warn">${html}</div>`;
const beyond = (html) => `<div class="note beyond"><b>Отвъд учебника.</b> ${html}</div>`;
const syn = (s) => `<pre class="syntax">${s.trim().replace(/</g, '&lt;')}</pre>`;
const sel = (id, db, title, text, solution, more = {}) => ({ id, kind: 'sql', type: 'select', db, title, text, solution, ...more });
const mod = (id, db, title, text, solution, check, more = {}) => ({ id, kind: 'sql', type: 'modify', db, title, text, solution, check, ...more });
const q = (id, title, text, options, answer, explain) => ({ id, kind: 'choice', title, text, options, answer, explain });
const B = { bonus: true };

